parameters.jsCode:
const item = $input.item;

function decodeMimeHeader(value) {
  if (!value) return '';
  return value.replace(/=\?UTF-8\?Q\?(.*?)\?=/gi, (_, encoded) => {
    const bytes = encoded
      .replace(/_/g, ' ')
      .replace(/=([A-Fa-f0-9]{2})/g, (_, hex) =>
        String.fromCharCode(parseInt(hex, 16))
      );
    return Buffer.from(bytes, 'latin1').toString('utf8');
  });
}

const headers = item.json.headers || {};
const subject = decodeMimeHeader(headers.subject || '')
  .replace(/^Subject:\s*/i, '')
  .trim();

const dateHeader = Object.entries(headers)
  .find(([key]) => key.toLowerCase() === 'date')?.[1];
const fechaIngreso = dateHeader
  ? new Date(dateHeader).toISOString()
  : new Date().toISOString();

const fromEntry = item.json.from?.value?.[0] || {};
const nombreSolicitante = fromEntry.name || '';
const emailSolicitante = fromEntry.address || '';

return {
  json: {
    ...item.json,
    asunto_limpio: subject,
    descripcion_limpia: item.json.text || item.json.snippet || '',
    fecha_ingreso_limpia: fechaIngreso,
    nombre_solicitante: nombreSolicitante,
    email_solicitante: emailSolicitante,
    gmail_message_id: item.json.id || '',
    gmail_thread_id: item.json.threadId || item.json.threadid || item.json.id || ''
  }
};

const raw = String($json.output ?? $json.text ?? '').trim();
const match = raw.match(/\{[\s\S]*\}/);
if (!match) {
  throw new Error('La IA no devolvió un JSON válido para clasificar la solicitud.');
}
const data = JSON.parse(match[0]);

const categorias = ['Personal', 'Compras y contrataciones', 'Trámites administrativos', 'Proyectos, subsidios y becas', 'Otros'];
const prioridades = ['Alta', 'Media', 'Baja'];
const areas = ['Administración IDEI', 'Dirección IDEI', 'Personal', 'Compras y Contrataciones', 'Secretaría'];

if (!categorias.includes(data.categoria)) throw new Error('Categoría de IA no válida.');
if (!prioridades.includes(data.prioridad)) throw new Error('Prioridad de IA no válida.');
if (!areas.includes(data.area_responsable)) throw new Error('Área responsable de IA no válida.');
if (!String(data.resumen ?? '').trim() || !String(data.respuesta_sugerida ?? '').trim()) {
  throw new Error('La IA devolvió campos de resumen o respuesta vacíos.');
}

const areaEsperada = {
  'Personal': 'Personal',
  'Compras y contrataciones': 'Compras y Contrataciones',
  'Trámites administrativos': 'Administración IDEI',
  'Otros': 'Administración IDEI',
};

if (areaEsperada[data.categoria] && data.area_responsable !== areaEsperada[data.categoria]) {
  throw new Error(
    'Inconsistencia categoría-área: ' +
    data.categoria + ' debe asignarse a ' + areaEsperada[data.categoria] +
    ', no a ' + data.area_responsable + '.'
  );
}

return {
  json: {
    categoria: data.categoria,
    prioridad: data.prioridad,
    area_responsable: data.area_responsable,
    resumen: String(data.resumen).trim(),
    respuesta_sugerida: String(data.respuesta_sugerida).trim(),
    requiere_revision: true,
    solicitud_id: $('Create a record').item.json.id
  }
};
